"""
build-batch-10-guides.py — Las 8 guías del lote 10 (una por calculadora de build-batch-10.py).
Generación de una sola vez: después, el HTML es la fuente de verdad.
"""
from spec_lib import S, g_formula, g_h2, g_p, g_steps, g_table, g_ul, guide_page, write_guide


def G(slug, name, title, desc, og, headline, intro, quick, cta, sections, faqs, related):
    write_guide(slug, guide_page(slug=slug, name=name, page_title=title, desc=desc, og_desc=og, headline=headline, intro=intro, quick=quick,
                                 cta=cta, body_html="\n\n".join(sections), faqs=faqs, related=related))


# ============================================================ 1. pendiente y distancia entre dos puntos
G("como-calcular-la-pendiente-y-la-distancia-entre-dos-puntos", "Cómo calcular la pendiente y la distancia entre dos puntos",
  "Cómo Calcular la Pendiente, la Recta y la Distancia entre Dos Puntos | Calculadora Científica",
  "Fórmulas de la pendiente, la ecuación de la recta que pasa por dos puntos, la distancia y el punto medio, con ejemplos resueltos paso a paso y rectas paralelas y perpendiculares.",
  "Pendiente, ecuación de la recta, distancia y punto medio entre dos puntos, con ejemplos.",
  "Cómo calcular la pendiente y la distancia entre dos puntos",
  "Con dos puntos del plano se puede hallar todo sobre la recta que los une: cuánto se inclina, su ecuación, qué tan lejos están y dónde queda el medio. Esta guía explica cada fórmula con ejemplos numéricos.",
  "m = (y₂ − y₁)/(x₂ − x₁) · y = m·x + b · d = √((x₂ − x₁)² + (y₂ − y₁)²) · M = ((x₁ + x₂)/2 ; (y₁ + y₂)/2).",
  ("/calculadoras/matematicas-avanzadas/recta-y-distancia-entre-puntos/", "Abrir calculadora"),
  [g_h2("1. La pendiente"),
   g_p("La pendiente mide la inclinación de una recta: cuánto cambia y por cada unidad que avanza x. Entre dos puntos se calcula dividiendo la diferencia de alturas por la diferencia de posiciones."),
   g_formula("m = (y₂ − y₁) / (x₂ − x₁)"),
   g_steps(["Puntos (1; 2) y (3; 6)", "m = (6 − 2) / (3 − 1) = 4 / 2 = 2"]),
   g_p("Una pendiente positiva indica una recta que sube de izquierda a derecha; una negativa, que baja; y cero, una recta horizontal."),
   g_h2("2. La ecuación de la recta"),
   g_formula("y = m·x + b &nbsp;&nbsp; con &nbsp; b = y₁ − m·x₁"),
   g_p("La ordenada al origen b es la altura a la que la recta corta al eje y. Para el ejemplo anterior: b = 2 − 2·1 = 0, así que la recta es " + S + "y = 2x</strong>."),
   g_steps(["Puntos (−2; 1) y (4; 9)", "m = (9 − 1) / (4 − (−2)) = 8 / 6 = 4/3 ≈ 1,333", "b = 1 − (4/3)·(−2) = 1 + 8/3 = 11/3 ≈ 3,667", "y = 1,333·x + 3,667"]),
   g_p("También se puede escribir en forma general, A·x + B·y + C = 0, con A = y₂ − y₁, B = x₁ − x₂ y C = x₂·y₁ − x₁·y₂."),
   g_h2("3. La distancia entre dos puntos"),
   g_p("Sale del teorema de Pitágoras: la diferencia en x y la diferencia en y son los catetos de un triángulo rectángulo, y la distancia es la hipotenusa."),
   g_formula("d = √((x₂ − x₁)² + (y₂ − y₁)²)"),
   g_steps(["Puntos (−2; 1) y (4; 9)", "Δx = 6 y Δy = 8", "d = √(36 + 64) = √100 = 10"]),
   g_h2("4. El punto medio"),
   g_formula("M = ((x₁ + x₂) / 2 ; (y₁ + y₂) / 2)"),
   g_p("Para (−2; 1) y (4; 9): M = (1; 5). Es el promedio de las coordenadas."),
   g_h2("5. Casos especiales"),
   g_ul(["Recta horizontal (y₁ = y₂): la pendiente es 0 y la ecuación es y = constante.", "Recta vertical (x₁ = x₂): la pendiente no está definida (habría una división por cero) y la ecuación es x = constante.",
         "Rectas paralelas: tienen la misma pendiente.", "Rectas perpendiculares: el producto de las pendientes es −1. La perpendicular a una recta de pendiente 2 tiene pendiente −1/2."]),
   g_h2("6. Errores comunes"),
   g_ul(["Restar las coordenadas en distinto orden en el numerador y el denominador (si empezás con y₂ − y₁, seguí con x₂ − x₁).", "Olvidar el signo negativo cuando una coordenada es negativa: x₂ − x₁ con x₁ = −2 es x₂ + 2.", "Confundir la distancia con la diferencia: la distancia siempre es positiva."])],
  [("¿Cómo se calcula la pendiente entre dos puntos?", "m = (y₂ − y₁)/(x₂ − x₁). Entre (1; 2) y (3; 6) da 2."),
   ("¿Cómo se halla la ecuación de la recta que pasa por dos puntos?", "Se calcula m y luego b = y₁ − m·x₁. La recta es y = m·x + b."),
   ("¿Cómo se calcula la distancia entre dos puntos?", "Con d = √((x₂ − x₁)² + (y₂ − y₁)²): el teorema de Pitágoras."),
   ("¿Qué pasa si la recta es vertical?", "La pendiente no está definida y la ecuación es x = constante.")],
  [("/calculadoras/matematicas-avanzadas/recta-y-distancia-entre-puntos/", "Calculadora de recta y distancia"), ("/guias/teorema-de-pitagoras-explicado/", "Guía: teorema de Pitágoras"), ("/guias/como-graficar-una-funcion/", "Guía: cómo graficar una función")])

