   g_table(["Sustancia", "c (J/g·°C)"], [["Agua líquida", "4,186"], ["Hielo", "2,09"], ["Vapor de agua", "2,01"], ["Aire", "1,005"], ["Aluminio", "0,897"], ["Hierro", "0,449"], ["Cobre", "0,385"], ["Plomo", "0,129"], ["Oro", "0,129"]]),
